#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/ANDROID_STYLE_UI.md ]] || { echo 'Apply the native Android-style Windows UI update first; run from the repository root.' >&2; exit 1; }
python3 - <<'WINDOWS_PARITY'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/lib/desktop_store.dart': '',
'desktop/hyper_player/test/desktop_store_test.dart': '',
'desktop/hyper_player/FEATURE_PARITY.md': '',
}
for name, data in files.items():
    path = Path(name)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(base64.b64decode(data))
print('Windows collections, IPTV import and subtitle controls added. Full parity is not complete. See FEATURE_PARITY.md.')
WINDOWS_PARITY
